import React, { useState } from 'react';
import {
    Box,
    Button,
    TextField,
    Typography,
    Modal
} from '@mui/material';
import { useSnackBar } from '../../FlowBuilder/Common/SnackBar/index.tsx';
import { ManagementActions } from '../../../Services/_actions/Management/management.actions.ts';
import { ProfileObject } from '../../../interfaces/Management.interface.ts';
// import {cloneProfileApi}

interface CloneModalProps {
    open: boolean;
    mode: boolean;
    onClose: (data: any | null) => void;
    profile: ProfileObject | null;
}

const CloneModal: React.FC<CloneModalProps> = ({ open, mode, onClose, profile }) => {
    const ManagementAction = ManagementActions();
    const [newName, setNewName] = useState<string>('');
    const { showSnackBar } = useSnackBar();
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);

    const handleCloneProfile = async () => {
        if (!newName.trim()) {
            setError('Name is required');
            return;
        }

        setError(null);
        setLoading(true);

        try {
            const cloneData = {
                clone_from_profile_id: profile?.id,
                new_organisation_id: profile?.organisation?.organisation_id,
                new_name: newName,
            };

            const result = await ManagementAction.cloneProfileApi(cloneData);
            onClose(result);
            showSnackBar('Clone Profile Sucessfully','success');
        } catch (error) {
            showSnackBar('Failed to clone profile:','error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Modal open={open} onClose={() => { onClose(null); }}>
            <Box
                sx={{
                    position: 'absolute',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    bgcolor: 'background.paper',
                    boxShadow: 24,
                    borderRadius: '8px',
                    p: 3,
                    width: 400,
                    maxHeight: '90vh',
                    overflowY: 'auto',
                }}
            >
                {profile && (
                    <>
                        <Typography gutterBottom>
                            You are about to clone profile <strong>{profile.name}</strong> within organisation <strong>{profile.organisation.name}</strong>.
                        </Typography>
                        <TextField
                            label={
                                <Typography component="span">
                                    Enter New Name <span style={{ color: 'red' }}>*</span>
                                </Typography>
                            }
                            fullWidth
                            sx={{ marginBottom: 2 }}
                            margin="dense"
                            variant="outlined"
                            size="small"
                            value={newName}
                            onChange={(e) => setNewName(e.target.value)}
                            error={!!error}
                            helperText={error}
                        />
                    </>
                )}
                <Box mt={3} display="flex" justifyContent="flex-end" gap={2}>
                    <Button variant="outlined" onClick={() => { onClose(null); }} size="small">
                        Cancel
                    </Button>
                    <Button
                        variant="contained"
                        color="primary"
                        size="small"
                        onClick={handleCloneProfile}
                    >
                        {loading ? 'Cloning...' : 'Clone Profile'}
                    </Button>
                </Box>
            </Box>
        </Modal>
    );
};

export default CloneModal;
